CREATE TABLE IF NOT EXISTS product_signals(product_id UUID PRIMARY KEY REFERENCES products(id) ON DELETE CASCADE,demand NUMERIC(5,2) NOT NULL,margin NUMERIC(5,2) NOT NULL,competition NUMERIC(5,2) NOT NULL,supplier_score NUMERIC(5,2) NOT NULL,shipping_score NUMERIC(5,2) NOT NULL,risk_score NUMERIC(5,2) NOT NULL,trend NUMERIC(5,2) NOT NULL,composite_score NUMERIC(5,2) NOT NULL,decision TEXT NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS market_profiles(market TEXT PRIMARY KEY,currency CHAR(3) NOT NULL,status TEXT NOT NULL DEFAULT 'review',payment_coverage NUMERIC(5,2) NOT NULL DEFAULT 0,regulatory_complexity NUMERIC(5,2) NOT NULL DEFAULT 0,supplier_coverage NUMERIC(5,2) NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agent_runs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),agent TEXT NOT NULL,task_type TEXT NOT NULL,risk TEXT NOT NULL,status TEXT NOT NULL,evidence JSONB NOT NULL,output JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
